 for c in contexts:
  x=np.array(np.load(DATA/f'raw/{c["record"]}/{c["record"]}.npy',mmap_mode='r')[c['start_sample']:c['start_sample']+c['n']]);f.write(json.dumps({'context':c['id'],'interval_convention':'half-open relative sample indices','clinical_annotations':False,'events':{f'channel{ch}-threshold{t}':runs(x[:,ch]>=t).tolist() for ch in [0,1] for t in [.5,1.]}})+'\n')
