a=json.load(open(OUT/'aggregate.json'));front=[]
for s in a:
 if s['method'] in ['ttsax_level_diagnostic','minmax']:continue
 if not any(t['mean_online_bytes_fraction']<=s['mean_online_bytes_fraction'] and t['accuracy']>=s['accuracy'] and (t['mean_online_bytes_fraction']<s['mean_online_bytes_fraction'] or t['accuracy']>s['accuracy']) for t in a if t['method'] not in ['ttsax_level_diagnostic','minmax']):front.append(s)
dump('read-cost-pareto.json',{'axis':'Mean logical online raw+summary bytes/full relevant bytes; no offline cost or latency','points':front,'limitation':'Task-specific EventIndex can dominate this axis; it scans all source data offline and supports only declared thresholds/workload. Not an end-to-end efficiency frontier.'})
dump('timing-caveats.json',{'fixed_decoder':'Fixed representation build times include reconstruction, and query times use already reconstructed memory arrays. They are audit costs, not deployable end-to-end compressed-query timing.','tree':'Python traversal wall clock includes raw broker accounting and copies; NumPy full scan is vectorized and already resident. Lower logical bytes does not imply faster wall clock.','raw_bytes':'Unique scalar float32 bytes fetched, per query. Index nodes may be reread and are counted per access. No physical disk-I/O measurement.','SQL':'Returned rows cannot establish SQLite pages scanned. Do not put Sonar on raw-broker byte frontier.','full_baseline':'All relevant channels counted: one channel for eight single-variable questions; two for ordering/cooccur. A bookkeeping correction changed only byte counts before aggregation, not predictions.','fixed_build_input_bytes':'Fixed encoder input_bytes denotes source-array extent, not measured touches; uniform can subsample. No fixed-encoder scan-cost ranking claimed.','sampling':'8 independent record clusters, 24 contexts, 240 correlated QA; CIs resample records, not individual questions.'})
